window.docContents[136].resolve({"/Basic-Types/Maps-and-Sets/#Lean-__________________--Basic-Types--Maps-and-Sets--Dependent-Tree-Based-Maps--Creation":{"contents":"Creates a new empty tree map. It is also possible and recommended to\nuse the empty collection notations ∅ and {} to create an empty tree map. simp replaces\nempty with ∅.\n\n","context":"Lean 中文参考手册\u0009Basic Types\u0009Maps and Sets\u0009Dependent Tree-Based Maps","header":"20.19.9.1. Creation","id":"/Basic-Types/Maps-and-Sets/#Lean-__________________--Basic-Types--Maps-and-Sets--Dependent-Tree-Based-Maps--Creation"},"/Functors___-Monads-and--do--Notation/Varieties-of-Monads/#The-Lean-Language-Reference--Functors___-Monads-and--do--Notation--Varieties-of-Monads--Exceptions--Transformer":{"contents":"向单子 m 添加类型为 ε 的异常。\n\n在带异常的变换后单子中运行底层单子的计算。\n\n把可能抛出异常的单子动作作为可能返回异常值的动作使用。这是 ExceptT.mk 的逆操作。\n\n返回值 a，既不抛出异常，也不产生任何其他效果。\n\n依次执行两个可能抛出异常的动作。通常通过 do 记法或 >>= 运算符使用。\n\n处理一个除抛出异常外不可能有_其他_效果的动作所抛出的异常。\n\n处理 ExceptT ε 变换器中产生的异常。\n\n把可能返回异常值的单子动作作为变换后单子中可能抛出相应异常的动作使用。这是 ExceptT.run 的逆操作。\n\n使用 f 变换成功计算的值。通常通过 <$> 运算符使用。\n\n使用函数 f 变换异常。这是 Except.mapError 的 ExceptT 版本。\n\n","context":"Lean 中文参考手册\u0009函子、单子与  do  记法\u0009单子的种类\u0009异常","header":"18.5.7.4. 变换器","id":"/Functors___-Monads-and--do--Notation/Varieties-of-Monads/#The-Lean-Language-Reference--Functors___-Monads-and--do--Notation--Varieties-of-Monads--Exceptions--Transformer"},"/releases/v4.25.0/#Lean-__________________--Release-Notes--Lean-4___25___0-_LPAR_2025-11-14_RPAR_--Highlights--Apply-___try-this___-Suggestions":{"contents":"#10524 adds support for interactivity (hover, go-to-definitions) for \"try this\"\nmessages that were introduced in #9966. In doing so, it moves the link\nto apply a suggestion to a separate [apply] button in front of the\nsuggestion.\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.25.0 (2025-11-14)\u0009Highlights","header":"Apply \"try this\" Suggestions","id":"/releases/v4.25.0/#Lean-__________________--Release-Notes--Lean-4___25___0-_LPAR_2025-11-14_RPAR_--Highlights--Apply-___try-this___-Suggestions"},"/releases/v4.28.0/#Lean-__________________--Release-Notes--Lean-4___28___0-_LPAR_2026-02-17_RPAR_--Highlights--Symbolic-Simulation-Framework":{"contents":"New lightweight symbolic simulation framework integrates with grind\nand enables the implementation of verification condition generators\nand symbolic execution engines.\n#12143 defines the\ncore API of this framework.\n\nFor design notes and implementation details, see:\n\n* #11788 — intro and\n  overview* #11825 — efficient\n  pattern matching and unification* #11837 — goal\n  transformation via backward chaining* #11860 —\n  congruence analysis for efficient subterm rewriting* #11884 —\n  discrimination tree for fast pattern retrieval* #11909 — monad\n  hierarchy for symbolic computation* #11898,\n  #11967,\n  #11974 —\n  optimizations\n\n","context":"Lean 中文参考手册\u0009Release Notes\u0009Lean 4.28.0 (2026-02-17)\u0009Highlights","header":"Symbolic Simulation Framework","id":"/releases/v4.28.0/#Lean-__________________--Release-Notes--Lean-4___28___0-_LPAR_2026-02-17_RPAR_--Highlights--Symbolic-Simulation-Framework"}});